<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal(); $pdo=db();$u=current_user();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=$_POST['senha_atual']??'';$n=$_POST['nova_senha']??'';$c=$_POST['confirmar']??'';$row=$pdo->prepare('SELECT * FROM usuarios WHERE id=?');$row->execute([$u['id']]);$row=$row->fetch();if(!password_verify($a,$row['senha_hash']))$error='Senha atual incorreta.';elseif(strlen($n)<6)$error='A nova senha deve possuir pelo menos 6 caracteres.';elseif($n!==$c)$error='As senhas não conferem.';else{$pdo->prepare('UPDATE usuarios SET senha_hash=?,primeiro_acesso=0,atualizado_em=? WHERE id=?')->execute([password_hash($n,PASSWORD_DEFAULT),now(),$u['id']]);$_SESSION['user']['first_access']=0;log_action('alteração de senha','usuarios',$u['id']);flash('success','Senha alterada com sucesso.');redirect('/admin/index.php');}}
include __DIR__.'/../../includes/header.php'; ?><div class="page-head"><div><h1>Alterar senha</h1><div class="muted">Por segurança, use pelo menos 6 caracteres.</div></div></div><div class="card"><?php if($error): ?><div class="alert danger"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field col-12"><label>Senha atual</label><input type="password" name="senha_atual" required></div><div class="field col-6"><label>Nova senha</label><input type="password" name="nova_senha" required></div><div class="field col-6"><label>Confirmar nova senha</label><input type="password" name="confirmar" required></div></div><div class="form-actions"><button class="btn primary">Alterar senha</button></div></form></div><?php include __DIR__.'/../../includes/footer.php'; ?>
